+package server_test
+
+import (
+	"context"
+	"encoding/json"
+	"io"
+	"net/http"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// newLink owns a user and a link in the test server's store.
+func newLink(t *testing.T, st store.Store, email, slug, target string) {
+	t.Helper()
+	u := &store.User{Email: email, PasswordHash: "x", CreatedAt: time.Now()}
+	if err := st.CreateUser(context.Background(), u); err != nil {
+		t.Fatal(err)
+	}
+	l := &store.Link{UserID: u.ID, Slug: slug, TargetURL: target, CreatedAt: time.Now()}
+	if err := st.CreateLink(context.Background(), l); err != nil {
+		t.Fatal(err)
+	}
+}
+
+func TestRedirect(t *testing.T) {
+	st, srv := newStoreAndServer(t)
+	newLink(t, st, "owner@example.com", "abc1234", "https://example.com/target")
+
+	res, err := srv.Client().Get(srv.URL + "/abc1234")
+	if err != nil {
+		t.Fatal(err)
+	}
+	body, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusFound {
+		t.Fatalf("GET /abc1234: %d %q, want 302", res.StatusCode, body)
+	}
+	if got := res.Header.Get("Location"); got != "https://example.com/target" {
+		t.Fatalf("Location %q, want https://example.com/target", got)
+	}
+	link, err := st.GetLinkBySlug(context.Background(), "abc1234")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if link.TotalClicks != 1 {
+		t.Fatalf("total clicks %d after one redirect, want 1", link.TotalClicks)
+	}
+	stats, err := st.GetClickStats(context.Background(), "abc1234", time.Now(), 30)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if got := stats.Days[len(stats.Days)-1]; got.Clicks != 1 || got.Date != utcDay(time.Now()) {
+		t.Fatalf("today's day %+v, want %s with 1 click", got, utcDay(time.Now()))
+	}
+}
+
+func TestRedirectUnknown(t *testing.T) {
+	_, srv := newStoreAndServer(t)
+	for _, path := range []string{"/unknown", "/nope123", "/zzzzzzz"} {
+		res, err := srv.Client().Get(srv.URL + path)
+		if err != nil {
+			t.Fatal(err)
+		}
+		body, _ := io.ReadAll(res.Body)
+		_ = res.Body.Close()
+		if res.StatusCode != http.StatusNotFound {
+			t.Errorf("GET %s: %d %q, want 404", path, res.StatusCode, body)
+		}
+	}
+}
+
+func TestStats(t *testing.T) {
+	st, srv := newStoreAndServer(t)
+	newLink(t, st, "owner@example.com", "statlink", "https://example.com/target")
+
+	var days []struct {
+		Date  string `json:"date"`
+		Count int64  `json:"count"`
+	}
+	if code := getJSONAsOwner(t, srv, "/api/links/statlink/stats", &days); code != http.StatusOK {
+		t.Fatalf("GET /api/links/statlink/stats: %d, want 200", code)
+	}
+	if len(days) != 30 {
+		t.Fatalf("%d entries, want 30", len(days))
+	}
+	start := utcMidnight(time.Now()).AddDate(0, 0, -29)
+	for i, d := range days {
+		if want := utcDay(start.AddDate(0, 0, i)); d.Date != want {
+			t.Fatalf("entry %d names %q, want %q", i, d.Date, want)
+		}
+		if d.Count != 0 {
+			t.Fatalf("entry %d counts %d clicks, want 0", i, d.Count)
+		}
+	}
+}
+
+func TestStatsAfterClicks(t *testing.T) {
+	st, srv := newStoreAndServer(t)
+	newLink(t, st, "owner@example.com", "statlink", "https://example.com/target")
+
+	noRedirect(t, srv, "/statlink")
+	noRedirect(t, srv, "/statlink")
+
+	var days []struct {
+		Date  string `json:"date"`
+		Count int64  `json:"count"`
+	}
+	if code := getJSONAsOwner(t, srv, "/api/links/statlink/stats", &days); code != http.StatusOK {
+		t.Fatalf("GET /api/links/statlink/stats: %d, want 200", code)
+	}
+	if len(days) != 30 {
+		t.Fatalf("%d entries, want 30", len(days))
+	}
+	want := utcDay(time.Now())
+	for i, d := range []struct {
+		Date  string
+		Count int64
+	}(days){
+		switch {
+		case d.Date == want && d.Count != 2:
+			t.Fatalf("day %d of %d counts %d clicks, want 2", i, len(days), d.Count)
+		case d.Date != want && d.Count != 0:
+			t.Fatalf("day %s counts %d clicks, want 0", d.Date, d.Count)
+		}
+	}
+	if days[len(days)-1].Date != want {
+		t.Fatalf("last entry names %q, want today %q", days[len(days)-1].Date, want)
+	}
+}
+
+func TestStatsNeedsAuth(t *testing.T) {
+	st, srv := newStoreAndServer(t)
+	newLink(t, st, "owner@example.com", "statlink", "https://example.com/target")
+
+	req, err := http.NewRequest(http.MethodGet, srv.URL+"/api/links/statlink/stats", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	res, err := srv.Client().Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	body, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusUnauthorized {
+		t.Fatalf("anonymous GET stats: %d %q, want 401", res.Statu
