+++ b/internal/server/routes_redirect_test.go
@@ -0,0 +1,251 @@
+package server_test
+
+import (
+	"context"
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/server"
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// newStoreAndServer serves the app over a store the test holds as well, so it
+// can seed rows and read what a request changed.
+func newStoreAndServer(t *testing.T) (store.Store, *httptest.Server) {
+	t.Helper()
+	st, err := store.Open(t.TempDir())
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { _ = st.Close() })
+	srv := httptest.NewServer(server.New(server.Config{Store: st}))
+	t.Cleanup(srv.Close)
+	return st, srv
+}
+
+// newLink seeds an owner and one of their links.
+func newLink(t *testing.T, st store.Store, email, slug, target string) *store.User {
+	t.Helper()
+	u := &store.User{Email: email, PasswordHash: "hash", CreatedAt: time.Now()}
+	if err := st.CreateUser(context.Background(), u); err != nil {
+		t.Fatal(err)
+	}
+	l := &store.Link{UserID: u.ID, Slug: slug, TargetURL: target, CreatedAt: time.Now()}
+	if err := st.CreateLink(context.Background(), l); err != nil {
+		t.Fatal(err)
+	}
+	return u
+}
+
+// loginSession seeds a live session for a user and names its token.
+func loginSession(t *testing.T, st store.Store, userID int64) string {
+	t.Helper()
+	token := strings.Repeat("a", 43)
+	sess := &store.Session{Token: token, UserID: userID, ExpiresAt: time.Now().Add(time.Hour)}
+	if err := st.CreateSession(context.Background(), sess); err != nil {
+		t.Fatal(err)
+	}
+	return token
+}
+
+// get answers a GET with no redirects followed and no cookie.
+func get(t *testing.T, srv *httptest.Server, path string) (*http.Response, []byte) {
+	t.Helper()
+	return doAs(t, srv, http.MethodGet, path, "")
+}
+
+// doAs answers a GET as the holder of a session cookie, or anonymously.
+func doAs(t *testing.T, srv *httptest.Server, method, path, session string) (*http.Response, []byte) {
+	t.Helper()
+	client := &http.Client{
+		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
+	}
+	req, err := http.NewRequest(method, srv.URL+path, nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if session != "" {
+		req.AddCookie(&http.Cookie{Name: server.SessionCookie, Value: session})
+	}
+	res, err := client.Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer func() { _ = res.Body.Close() }()
+	body, err := io.ReadAll(res.Body)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return res, body
+}
+
+func TestRedirect(t *testing.T) {
+	st, srv := newStoreAndServer(t)
+	newLink(t, st, "owner@example.com", "abc1234", "https://example.com/target")
+
+	res, body := get(t, srv, "/abc1234")
+	if res.StatusCode != http.StatusFound {
+		t.Fatalf("GET /abc1234: %d %q, want 302", res.StatusCode, body)
+	}
+	if got := res.Header.Get("Location"); got != "https://example.com/target" {
+		t.Fatalf("Location %q, want https://example.com/target", got)
+	}
+	link, err := st.GetLinkBySlug(context.Background(), "abc1234")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if link.TotalClicks != 1 {
+		t.Fatalf("total clicks %d after one redirect, want 1", link.TotalClicks)
+	}
+	stats, err := st.GetClickStats(context.Background(), "abc1234", time.Now(), 30)
+	if err != nil {
+		t.Fatal(err)
+	}
+	today := stats.Days[len(stats.Days)-1]
+	if today.Date != utcDay(time.Now()) || today.Clicks != 1 {
