+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// statsDays is how many UTC days of clicks the stats endpoint returns.
+const statsDays = 30
+
+func init() {
+	addRoutes(func(s *Server) {
+		s.HandleFunc("GET /api/links/{slug}/stats", s.linkStats)
+		// The short link: one segment under / that is none of the app's own
+		// prefixes, so it cannot clash with /api/, /app/ or /healthz.
+		s.HandleFunc("GET /{slug}", s.redirect)
+	})
+}
+
+// redirect counts a click on the slug and answers 302 to its target; an
+// unknown slug answers 404.
+func (s *Server) redirect(w http.ResponseWriter, r *http.Request) {
+	slug := r.PathValue("slug")
+	if !redirectableSlug(slug) {
+		writeError(w, http.StatusNotFound)
+		return
+	}
+	if err := s.store.IncrementClick(r.Context(), slug, time.Now()); err != nil {
+		if errors.Is(err, store.ErrNotFound) {
+			writeError(w, http.StatusNotFound)
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	link, err := s.store.GetLinkBySlug(r.Context(), slug)
+	if err != nil {
+		if errors.Is(err, store.ErrNotFound) {
+			writeError(w, http.StatusNotFound)
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	http.Redirect(w, r, link.TargetURL, http.StatusFound)
+}
+
+// redirectableSlug accepts what the links API can hand out: 7 random base62
+// characters, or a custom slug of [a-z0-9-] from 3 to 32. Anything else, the
+// reserved prefixes above all, answers 404 without touching the database.
+func redirectableSlug(slug string) bool {
+	if len(slug) < 3 || len(slug) > 32 {
+		return false
+	}
+	for i := 0; i < len(slug); i++ {
+		c := slug[i]
+		between := c >= 'a' && c <= 'z' || c >= '0' && c <= '9'
+		if i == len(slug)-1 {
+			// A custom slug may not end in a dash; random ones never do.
+			between = between || c == '-'
+		} else {
+			between = between || c == '-' || (c >= 'A' && c <= 'Z')
+		}
+		if !between {
+			return false
+		}
+	}
+	return true
+}
+
+// dayStat is one UTC day of clicks as the stats endpoint writes it.
+type dayStat struct {
+	Date  string `json:"date"`
+	Count int64  `json:"count"`
+}
