+// linkStats answers the link's clicks per UTC day of the last 30 days, oldest
+// first. It needs a login, and a link of another user answers 404.
+func (s *Server) linkStats(w http.ResponseWriter, r *http.Request) {
+	userID, ok := requireUser(w, r)
+	if !ok {
+		return
+	}
+	slug := r.PathValue("slug")
+	link, err := s.store.GetLinkBySlug(r.Context(), slug)
+	if err != nil {
+		if errors.Is(err, store.ErrNotFound) {
+			writeError(w, http.StatusNotFound)
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	if link.UserID != userID {
+		writeError(w, http.StatusNotFound)
+		return
+	}
+	stats, err := s.store.GetClickStats(r.Context(), slug, time.Now(), statsDays)
+	if err != nil {
+		if errors.Is(err, store.ErrNotFound) {
+			writeError(w, http.StatusNotFound)
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	days := make([]dayStat, 0, len(stats.Days))
+	for _, d := range stats.Days {
+		days = append(days, dayStat{Date: d.Date, Count: d.Clicks})
+	}
+	writeJSON(w, http.StatusOK, days)
+}
